        cLib_addCalc2(&mCirclePath.mRadius, radius, 0.1f, 100.0f);
        mCirclePath.mWobbleAmplitude = 200.0f + REG12_F(1);
        mCirclePath.mAngleSpeed = (REG12_S(0) + 0x150) * dir;
